import{_ as d,o as e,c as a,a5 as o}from"./chunks/framework.CwYPcpF1.js";const u=JSON.parse('{"title":"即时翻译","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/quick-translate.md","filePath":"zh/guide/quick-translate.md"}'),r={name:"zh/guide/quick-translate.md"};function i(l,t,s,n,h,c){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="即时翻译" tabindex="-1">即时翻译 <a class="header-anchor" href="#即时翻译" aria-label="Permalink to &quot;即时翻译&quot;">​</a></h1><p>不想建项目、不想上传文件，只想把一段文字丢进去看译文？<strong>即时翻译</strong>就是为这个准备的。</p><p>它复用项目翻译同一套执行计划、术语表与流水线，但 <strong>单段、临时、不落库</strong>——译文只给你看，关掉页面就没了。</p><div class="tip custom-block"><p class="custom-block-title">和谁有关</p><ul><li>想快速试一个执行计划 / 提示词 / 模型的效果</li><li>有一段零散文本要立刻译，不需要存档</li><li>想在正式建项目前先验证语言方向与术语是否对路</li></ul></div><h2 id="在哪里用" tabindex="-1">在哪里用 <a class="header-anchor" href="#在哪里用" aria-label="Permalink to &quot;在哪里用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>说明</th></tr></thead><tbody><tr><td><strong>首页 / 开始翻译</strong>（<code>QuickTranslateWidget</code>）</td><td>顶部首页即是一个即时翻译卡片，粘贴 → 选计划 → 出结果</td></tr><tr><td><strong>工具 → 即时翻译</strong>（独立页）</td><td>同样的能力，单独全宽页面，方便长期挂着</td></tr></tbody></table><p>两个入口指向同一个能力，只是版式不同。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><ol><li><strong>粘贴或输入原文</strong> — 单段文本，可含多句</li><li><strong>选择语言</strong> — 源语言可留 <code>auto</code>（自动检测）；目标语言默认 <code>zh</code>，可改</li><li><strong>选择执行计划</strong> — 必选；计划决定用哪个后端、几轮翻译、是否带裁决 / 语义质检</li><li><strong>（可选）挂项目术语表</strong> — 选一个项目，翻译时自动套用该项目的术语规则与语言配置</li><li><strong>（可选）内联术语表</strong> — 当场填几条 <code>源 → 目标</code> 临时术语；项目场景下叠加在项目术语表之上</li><li><strong>点击翻译</strong>，等待结果</li></ol><div class="warning custom-block"><p class="custom-block-title">译文不落库</p><p>即时翻译在内存里跑完即丢。<strong>不会</strong>写入任何项目、资源或段落。要想保留译文，请复制出来，或改用 <a href="/LinguaFlow/zh/guide/projects.html">项目 / 资源翻译</a>。</p></div><h2 id="结果展示" tabindex="-1">结果展示 <a class="header-anchor" href="#结果展示" aria-label="Permalink to &quot;结果展示&quot;">​</a></h2><p>翻译完成后，页面会给出：</p><table tabindex="0"><thead><tr><th>区域</th><th>内容</th></tr></thead><tbody><tr><td><strong>译文</strong></td><td>目标语言结果；失败时可能为空</td></tr><tr><td><strong>质量标记</strong></td><td>沿用流水线的规则质检结果（如长度比、源语残留等），与项目翻译一致</td></tr><tr><td><strong>轮次概览</strong></td><td>每一轮的模式、后端、状态、耗时。多轮计划会列出多行</td></tr><tr><td><strong>诊断详情</strong></td><td>每批次的 system prompt / user message / 响应原文 / token 用量（隐私裁剪，不含 API Key）</td></tr><tr><td><strong>用量</strong></td><td>API 调用次数、输入 / 输出 token 数</td></tr><tr><td><strong>警告</strong></td><td>流水线在运行中遇到的非致命提示</td></tr></tbody></table><h3 id="轮次状态" tabindex="-1">轮次状态 <a class="header-anchor" href="#轮次状态" aria-label="Permalink to &quot;轮次状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><code>success</code></td><td>该轮全部完成</td></tr><tr><td><code>partial</code></td><td>该轮部分段失败（仍产出可用译文）</td></tr><tr><td><code>failed</code></td><td>该轮失败，没有可用译文</td></tr><tr><td><code>skipped</code></td><td>该轮因目标段状态不满足 <code>segment_filter</code> 被跳过，译文沿用上一轮结果</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title"><code>skipped</code> 何时出现</p><p>单段即时翻译首轮一定会执行；只有 <strong>多轮翻译计划</strong> 的后续轮次才可能 <code>skipped</code>——因为目标段只有一条，首轮译完状态变化后，后续轮按过滤策略可能判定「无需再译」。</p><p>这与 <a href="/LinguaFlow/zh/guide/translation-config.html#单段试译">单段试译</a> 的多轮过滤语义一致，详见 <a href="/LinguaFlow/zh/guide/pipeline.html#多轮试译的过滤语义">流水线与原理 · 多轮试译的过滤语义</a>。</p></div><h2 id="术语表叠加规则" tabindex="-1">术语表叠加规则 <a class="header-anchor" href="#术语表叠加规则" aria-label="Permalink to &quot;术语表叠加规则&quot;">​</a></h2><p>即时翻译可同时使用项目术语表 + 内联术语表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>最终生效术语 = 项目术语表（若选了项目）∪ 内联术语表（若填了）</span></span></code></pre></div><p>内联术语表每条可设：</p><table tabindex="0"><thead><tr><th>字段</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>source</code></td><td>（必填）</td><td>源术语</td></tr><tr><td><code>target</code></td><td>（必填）</td><td>目标译法</td></tr><tr><td><code>case_sensitive</code></td><td><code>false</code></td><td>是否区分大小写</td></tr><tr><td><code>forbidden</code></td><td><code>false</code></td><td>禁译：译文中<strong>不应</strong>出现这个 target</td></tr><tr><td><code>mandatory</code></td><td><code>true</code></td><td>强制：命中 source 时必须用这个 target</td></tr><tr><td><code>notes</code></td><td>（可选）</td><td>备注，注入给模型作提示</td></tr></tbody></table><p>术语规则的运作方式（命中后做什么、如何触发质检）见 <a href="/LinguaFlow/zh/guide/glossary.html#禁译-forbidden-与强制-mandatory">术语表管理 · 禁译 / 强制</a>。</p><h2 id="和单段试译、项目翻译的区别" tabindex="-1">和单段试译、项目翻译的区别 <a class="header-anchor" href="#和单段试译、项目翻译的区别" aria-label="Permalink to &quot;和单段试译、项目翻译的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>即时翻译</th><th><a href="/LinguaFlow/zh/guide/translation-config.html#单段试译">单段试译</a></th><th><a href="/LinguaFlow/zh/guide/projects.html">项目翻译</a></th></tr></thead><tbody><tr><td>入口</td><td>首页 / 工具页</td><td>工作区 → 段落行</td><td>工作区 → 资源 / 作业</td></tr><tr><td>输入</td><td>任意粘贴文本</td><td>已存在的段落原文（可临时改）</td><td>已上传的资源文件</td></tr><tr><td>数据落库</td><td>❌ 不落库</td><td>只有显式「应用译文」才写回段落</td><td>译文写入段落、可审校、可导出</td></tr><tr><td>术语来源</td><td>内联 + 可选项目</td><td>项目术语表（临时覆盖层）</td><td>项目术语表</td></tr><tr><td>适合</td><td>临时翻译、快速试计划</td><td>段落级试效果再决定要不要覆盖</td><td>正式批量本地化</td></tr></tbody></table><p>简单判断：</p><ul><li><strong>只想译一段、不留底</strong> → 即时翻译</li><li><strong>已有项目段落、想试某计划对它的效果</strong> → 单段试译</li><li><strong>要批量、可审校、可导出</strong> → 项目翻译</li></ul><h2 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h2><ul><li><strong>单段</strong>：一次翻译一段文本（可含多句）。整篇文档请走项目翻译。</li><li><strong>并发受限</strong>：即时翻译有独立的并发上限（默认每用户 2、全局 8），见 <a href="/LinguaFlow/zh/guide/configuration.html#quick-translate-即时翻译">配置文件与环境变量 · 即时翻译</a>。提示「并发已满」时稍后重试即可。</li><li><strong>超时</strong>：默认单次 5 分钟（与单段试译一致，因含 429 指数退避，单轮 LLM 调用可能较慢）。服务器管理员可在 <code>server.quick_translate.timeout</code> / <code>max_timeout</code> 调整。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/LinguaFlow/zh/guide/getting-started.html">快速开始 · Web</a> — 项目化批量翻译的完整流程</li><li><a href="/LinguaFlow/zh/guide/translation-config.html">翻译配置 · 使用</a> — 执行计划、术语、单段试译</li><li><a href="/LinguaFlow/zh/guide/configuration.html#quick-translate-即时翻译">配置文件与环境变量</a> — 后端配置项</li></ul>',30)])])}const p=d(r,[["render",i]]);export{u as __pageData,p as default};
